l,"CourseCredit":null,"Ects":7,"_programmeKey":"PRG-0050","_courseKey":"CRS-B0EDD498C6F2439FBB6C5CEBB1F66109"}]}$catalog_data$::jsonb;
  item jsonb;
  wanted jsonb;
  existing jsonb;
  parent_id integer;
  matches bigint;
  differences text;
  added integer := 0;
  skipped integer := 0;
  total_added integer := 0;
  total_skipped integer := 0;
BEGIN
  IF current_database() <> 'UniversityDecisionHub' THEN
    RAISE EXCEPTION 'Wrong database. Select your local UniversityDecisionHub database.';
  END IF;
  IF EXISTS (SELECT 1 FROM (VALUES ('20261013171125_InitialCourses'),
('20261022000000_AddRecommendedStudyYear'),
('20261024204904_AddAcademicCatalog'),
('20261024205903_AddReviewSubmission'),
('20261110152153_IntegrateAuthenticationAccounts'),
('20261110193326_AddCatalogImportKeys'),
('20261114203731_AddProgrammeFoundation'),
('20261114204921_AlignCatalogAndReviewWorkflow')) AS required(id)
             WHERE NOT EXISTS (SELECT 1 FROM public."__EFMigrationsHistory" h WHERE h."MigrationId" = required.id)) THEN
    RAISE EXCEPTION 'Required migrations are missing. No catalogue import performed.';
  END IF;
  LOCK TABLE public."Faculties", public."Departments", public."Instructors", public."Programmes", public."Courses", public."ProgrammeCourses" IN SHARE ROW EXCLUSIVE MODE;
  -- Faculties: 9 source records.
  added := 0; skipped := 0;
  FOR item IN SELECT value FROM jsonb_array_elements(data->'faculties') LOOP
    wanted := item;
    SELECT count(*) INTO matches FROM public."Faculties" t WHERE upper(btrim(t."ImportKey")) = wanted->>'ImportKey';
    IF matches > 1 THEN
      RAISE EXCEPTION 'Faculties: duplicate stable key %', wanted->>'ImportKey';
    ELSIF matches = 1 THEN
      SELECT to_jsonb(t) INTO STRICT existing FROM public."Faculties" t WHERE upper(btrim(t."ImportKey")) = wanted->>'ImportKey';
      SELECT string_agg(v.key, ', ' ORDER BY v.key) INTO differences
        FROM jsonb_each(wanted) v WHERE (existing->v.key) IS DISTINCT FROM v.value;
      IF differences IS NOT NULL THEN
        RAISE EXCEPTION 'Faculties key % differs in %. No overwrite performed.', wanted->>'ImportKey', differences;
      END IF;
      skipped := skipped + 1;
    ELSE
      IF EXISTS (SELECT 1 FROM public."Faculties" t WHERE upper(btrim(t."FacultyName")) = upper(wanted->>'FacultyName')) THEN
        RAISE EXCEPTION 'Faculties: ambiguous legacy identity for key %. Reconcile explicitly.', wanted->>'ImportKey';
      END IF;
      INSERT INTO public."Faculties" ("ImportKey", "FacultyName")
        SELECT r."ImportKey", r."FacultyName" FROM jsonb_populate_record(NULL::public."Faculties", wanted) r;
      added := added + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'Faculties: % added, % unchanged (commit pending)', added, skipped;
  total_added := total_added + added; total_skipped := total_skipped + skipped;
  -- Departments: 130 source records.
  added := 0; skipped := 0;
  FOR item IN SELECT value FROM jsonb_array_elements(data->'departments') LOOP
    wanted := item;
    SELECT "FacultyId" INTO STRICT parent_id FROM public."Faculties"
      WHERE upper(btrim("ImportKey")) = item->>'_facultyKey';
    wanted := (wanted - '_facultyKey') || jsonb_build_object('FacultyId', parent_id);
    SELECT count(*) INTO matches FROM public."Departments" t WHERE upper(btrim(t."DepartmentKey")) = wanted->>'DepartmentKey';
    IF matches > 1 THEN
      RAISE EXCEPTION 'Departments: duplicate stable key %', wanted->>'DepartmentKey';
    ELSIF matches = 1 THEN
      SELECT to_jsonb(t) INTO STRICT existing FROM public."Departments" t WHERE upper(btrim(t."DepartmentKey")) = wanted->>'DepartmentKey';
      SELECT string_agg(v.key, ', ' ORDER BY v.key) INTO differences
        FROM jsonb_each(wanted) v WHERE (existing->v.key) IS DISTINCT FROM v.value;
      IF differences IS NOT NULL THEN
        RAISE EXCEPTION 'Departments key % differs in %. No overwrite performed.', wanted->>'DepartmentKey', differences;
      END IF;
      skipped := skipped + 1;
    ELSE
      IF EXISTS (SELECT 1 FROM public."Departments" t WHERE t."FacultyId" = (wanted->>'FacultyId')::integer AND upper(btrim(t."DepartmentName")) = upper(wanted->>'DepartmentName')) THEN
        RAISE EXCEPTION 'Departments: ambiguous legacy identity for key %. Reconcile explicitly.', wanted->>'DepartmentKey';
      END IF;
      INSERT INTO public."Departments" ("DepartmentKey", "DepartmentCode", "DepartmentName", "FacultyId")
        SELECT r."DepartmentKey", r."DepartmentCode", r."DepartmentName", r."FacultyId" FROM jsonb_populate_record(NULL::public."Departments", wanted) r;
      added := added + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'Departments: % added, % unchanged (commit pending)', added, skipped;
  total_added := total_added + added; total_skipped := total_skipped + skipped;
  -- Instructors: 452 source records.
  added := 0; skipped := 0;
  FOR item IN SELECT value FROM jsonb_array_elements(data->'instructors') LOOP
    wanted := item;
    SELECT "DepartmentId" INTO STRICT parent_id FROM public."Departments"
      WHERE upper(btrim("DepartmentKey")) = item->>'_departmentKey';
    wanted := (wanted - '_departmentKey') || jsonb_build_object('DepartmentId', parent_id);
    SELECT count(*) INTO matches FROM public."Instructors" t WHERE upper(btrim(t."ImportKey")) = wanted->>'ImportKey';
    IF matches > 1 THEN
      RAISE EXCEPTION 'Instructors: duplicate stable key %', wanted->>'ImportKey';
    ELSIF matches = 1 THEN
      SELECT to_jsonb(t) INTO STRICT existing FROM public."Instructors" t WHERE upper(btrim(t."ImportKey")) = wanted->>'ImportKey';
      SELECT string_agg(v.key, ', ' ORDER BY v.key) INTO differences
        FROM jsonb_each(wanted) v WHERE (existing->v.key) IS DISTINCT FROM v.value;
      IF differences IS NOT NULL THEN
        RAISE EXCEPTION 'Instructors key % differs in %. No overwrite performed.', wanted->>'ImportKey', differences;
      END IF;
      skipped := skipped + 1;
    ELSE
      IF EXISTS (SELECT 1 FROM public."Instructors" t WHERE t."ImportKey" IS NULL AND upper(btrim(t."FullName")) = upper(wanted->>'FullName')) THEN
        RAISE EXCEPTION 'Instructors: ambiguous legacy identity for key %. Reconcile explicitly.', wanted->>'ImportKey';
      END IF;
      INSERT INTO public."Instructors" ("ImportKey", "FullName", "AcademicTitle", "DepartmentId")
        SELECT r."ImportKey", r."FullName", r."AcademicTitle", r."DepartmentId" FROM jsonb_populate_record(NULL::public."Instructors", wanted) r;
      added := added + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'Instructors: % added, % unchanged (commit pending)', added, skipped;
  total_added := total_added + added; total_skipped := total_skipped + skipped;
  -- Programmes: 92 source records.
  added := 0; skipped := 0;
  FOR item IN SELECT value FROM jsonb_array_elements(data->'programmes') LOOP
    wanted := item;
    SELECT "DepartmentId" INTO STRICT parent_id FROM public."Departments"
      WHERE upper(btrim("DepartmentKey")) = item->>'_departmentKey';
    wanted := (wanted - '_departmentKey') || jsonb_build_object('DepartmentId', parent_id);
    SELECT count(*) INTO matches FROM public."Programmes" t WHERE upper(btrim(t."ProgrammeKey")) = wanted->>'ProgrammeKey';
    IF matches > 1 THEN
      RAISE EXCEPTION 'Programmes: duplicate stable key %', wanted->>'ProgrammeKey';
    ELSIF matches = 1 THEN
      SELECT to_jsonb(t) INTO STRICT existing FROM public."Programmes" t WHERE upper(btrim(t."ProgrammeKey")) = wanted->>'ProgrammeKey';
      SELECT string_agg(v.key, ', ' ORDER BY v.key) INTO differences
        FROM jsonb_each(wanted) v WHERE (existing->v.key) IS DISTINCT FROM v.value;
      IF differences IS NOT NULL THEN
        RAISE EXCEPTION 'Programmes key % differs in %. No overwrite performed.', wanted->>'ProgrammeKey', differences;
      END IF;
      skipped := skipped + 1;
    ELSE
      INSERT INTO public."Programmes" ("ProgrammeKey", "ProgrammeName", "DegreeLevel", "InstructionLanguage", "BolognaProgrammeId", "DepartmentId")
        SELECT r."ProgrammeKey", r."ProgrammeName", r."DegreeLevel", r."InstructionLanguage", r."BolognaProgrammeId", r."DepartmentId" FROM jsonb_populate_record(NULL::public."Programmes", wanted) r;
      added := added + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'Programmes: % added, % unchanged (commit pending)', added, skipped;
  total_added := total_added + added; total_skipped := total_skipped + skipped;
  -- Courses: 303 source records.
  added := 0; skipped := 0;
  FOR item IN SELECT value FROM jsonb_array_elements(data->'courses') LOOP
    wanted := item;
    SELECT "DepartmentId" INTO STRICT parent_id FROM public."Departments"
      WHERE upper(btrim("DepartmentKey")) = item->>'_departmentKey';
    wanted := (wanted - '_departmentKey') || jsonb_build_object('DepartmentId', parent_id);
    SELECT count(*) INTO matches FROM public."Courses" t WHERE upper(btrim(t."CourseKey")) = wanted->>'CourseKey';
    IF matches > 1 THEN
      RAISE EXCEPTION 'Courses: duplicate stable key %', wanted->>'CourseKey';
    ELSIF matches = 1 THEN
      SELECT to_jsonb(t) INTO STRICT existing FROM public."Courses" t WHERE upper(btrim(t."CourseKey")) = wanted->>'CourseKey';
      SELECT string_agg(v.key, ', ' ORDER BY v.key) INTO differences
        FROM jsonb_each(wanted) v WHERE (existing->v.key) IS DISTINCT FROM v.value;
      IF differences IS NOT NULL THEN
        RAISE EXCEPTION 'Courses key % differs in %. No overwrite performed.', wanted->>'CourseKey', differences;
      END IF;
      skipped := skipped + 1;
    ELSE
      IF EXISTS (SELECT 1 FROM public."Courses" t WHERE t."DepartmentId" = (wanted->>'DepartmentId')::integer AND upper(btrim(t."CourseCode")) = upper(wanted->>'CourseCode')) THEN
        RAISE EXCEPTION 'Courses: ambiguous legacy identity for key %. Reconcile explicitly.', wanted->>'CourseKey';
      END IF;
      INSERT INTO public."Courses" ("CourseKey", "CourseCode", "CourseName", "CourseDescription", "RecommendedStudyYear", "CourseCredit", "Ects", "IsActive", "IsElective", "DepartmentId")
        SELECT r."CourseKey", r."CourseCode", r."CourseName", r."CourseDescription", r."RecommendedStudyYear", r."CourseCredit", r."Ects", r."IsActive", r."IsElective", r."DepartmentId" FROM jsonb_populate_record(NULL::public."Courses", wanted) r;
      added := added + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'Courses: % added, % unchanged (commit pending)', added, skipped;
  total_added := total_added + added; total_skipped := total_skipped + skipped;
  -- ProgrammeCourses: 316 source records.
  added := 0; skipped := 0;
  FOR item IN SELECT value FROM jsonb_array_elements(data->'programmeCourses') LOOP
    wanted := item;
    SELECT "ProgrammeId" INTO STRICT parent_id FROM public."Programmes"
      WHERE upper(btrim("ProgrammeKey")) = item->>'_programmeKey';
    wanted := (wanted - '_programmeKey') || jsonb_build_object('ProgrammeId', parent_id);
    SELECT "CourseId" INTO STRICT parent_id FROM public."Courses"
      WHERE upper(btrim("CourseKey")) = item->>'_courseKey';
    wanted := (wanted - '_courseKey') || jsonb_build_object('CourseId', parent_id);
    SELECT count(*) INTO matches FROM public."ProgrammeCourses" t WHERE upper(btrim(t."CurriculumKey")) = wanted->>'CurriculumKey';
    IF matches > 1 THEN
      RAISE EXCEPTION 'ProgrammeCourses: duplicate stable key %', wanted->>'CurriculumKey';
    ELSIF matches = 1 THEN
      SELECT to_jsonb(t) INTO STRICT existing FROM public."ProgrammeCourses" t WHERE upper(btrim(t."CurriculumKey")) = wanted->>'CurriculumKey';
      SELECT string_agg(v.key, ', ' ORDER BY v.key) INTO differences
        FROM jsonb_each(wanted) v WHERE (existing->v.key) IS DISTINCT FROM v.value;
      IF differences IS NOT NULL THEN
        RAISE EXCEPTION 'ProgrammeCourses key % differs in %. No overwrite performed.', wanted->>'CurriculumKey', differences;
      END IF;
      skipped := skipped + 1;
    ELSE
      INSERT INTO public."ProgrammeCourses" ("CurriculumKey", "CatalogueYear", "Semester", "RecommendedStudyYear", "IsElective", "CourseCredit", "Ects", "ProgrammeId", "CourseId")
        SELECT r."CurriculumKey", r."CatalogueYear", r."Semester", r."RecommendedStudyYear", r."IsElective", r."CourseCredit", r."Ects", r."ProgrammeId", r."CourseId" FROM jsonb_populate_record(NULL::public."ProgrammeCourses", wanted) r;
      added := added + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'ProgrammeCourses: % added, % unchanged (commit pending)', added, skipped;
  total_added := total_added + added; total_skipped := total_skipped + skipped;
  IF total_added + total_skipped <> 1302 THEN RAISE EXCEPTION 'Unexpected processed count'; END IF;
  RAISE NOTICE 'TOTAL: % added, % unchanged. Changes persist only if COMMIT succeeds.', total_added, total_skipped;
END;
$catalog_import$;
COMMIT;
-- Require a successful COMMIT. NOTICE lines alone do not prove commit.
SELECT current_database() AS database_name,
       inet_server_addr() AS server_address, inet_server_port() AS server_port;
SELECT 'Faculties' AS table_name, count(*) AS row_count FROM public."Faculties"
UNION ALL SELECT 'Departments', count(*) FROM public."Departments"
UNION ALL SELECT 'Instructors', count(*) FROM public."Instructors"
UNION ALL SELECT 'Programmes', count(*) FROM public."Programmes"
UNION ALL SELECT 'Courses', count(*) FROM public."Courses"
UNION ALL SELECT 'ProgrammeCourses', count(*) FROM public."ProgrammeCourses";
